@pytest.mark.parametrize("username, password, expected_status", [
    (None, None, 400),  # Missing username and password
    ("invalid_user", "invalid_pass", 400),  # Invalid username/password
    ("testuser", "testpassword", 200)  # Valid credentials
])
def test_login_user(api_client, username, password, expected_status):
    """
    Test the /user/login endpoint with various scenarios.
    """
    params = {}
    if username is not None:
        params["username"] = username
    if password is not None:
        params["password"] = password

    response = api_client.get(f"{BASE_URL}/user/login", params=params)

    assert response.status_code == expected_status

    if response.status_code == 200:
        # Validate response headers
        assert "X-Rate-Limit" in response.headers
        assert "X-Expires-After" in response.headers

        # Validate content type
        assert response.headers["Content-Type"] in ["application/xml", "application/json"]

        # Validate response body (string type)
        assert isinstance(response.text, str)

    elif response.status_code == 400:
        # Invalid username/password error
        assert response.json()["message"] == "Invalid username/password supplied"

    else:
        # Unexpected scenarios
        raise ValueError(f"Unexpected status code: {response.status_code}")


